function Root_ShowSkillProcess:InitNode()
    local posOrigin = Vector2.New(150, -40)
    self.listNode = {}
    for i = 1, 4 do
        local go = KTool.Instantiate(self.controller.gameObject, self.Node_ElementSkillProcess.gameObject)
        --KTool.SetActive(go, true)
        self:SetNodeProcessDesc(go, self:SetProcessValue(i))
        --self:SetNodeDesc(go, "")
        --self:SetNodeColor(go, self:GetNodeColor(1))
        table.insert(self.listNode, go)
        go.transform.anchoredPosition = Vector2.New(posOrigin.x, posOrigin.y - 90 * (i - 1))
    end
end

function Root_ShowSkillProcess:AddListener()
    self.eventSkillStart = Events.AddListener(Constants.EventNames.BattleSkillStartShow, Bind(self, self.SetNodeSkillStart))
    self.eventSkillEnd = Events.AddListener(Constants.EventNames.BattleSkillEndShow, Bind(self, self.SetNodeSkillEnd))
    self.eventSkillPrepareStart = Events.AddListener(Constants.EventNames.BattlePrepareStartShow, Bind(self, self.SetNodePrepareStart))
    self.eventSkillPrepareEnd = Events.AddListener(Constants.EventNames.BattlePrepareEndShow, Bind(self, self.SetNodePrepareEnd))
end

function Root_ShowSkillProcess:RemoveListener()
    Events.RemoveListener(Constants.EventNames.BattleSkillStartShow, self.eventSkillStart)
    Events.RemoveListener(Constants.EventNames.BattleSkillEndShow, self.eventSkillEnd)
    Events.RemoveListener(Constants.EventNames.BattlePrepareStartShow, self.eventSkillPrepareStart)
    Events.RemoveListener(Constants.EventNames.BattlePrepareEndShow, self.eventSkillPrepareEnd)
end

function Root_ShowSkillProcess:SetNodeSkillStart(data)
    local go = self.listNode[1]
    if self.coSkillStart then
        cs_coroutine.stop(self.coSkillStart)
        KTool.SetActive(go, false)
        self.coSkillStart = nil
    end
    if checkInt(data.star) >= 3 then return end
    self.coSkillStart = cs_coroutine.start(function()
        KTool.SetActive(go, true)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(SHOW_TIME))
        KTool.SetActive(go, false)
    end)
end

function Root_ShowSkillProcess:SetNodeSkillEnd(data)
    local go = self.listNode[4]
    if self.coSkillEnd then
        cs_coroutine.stop(self.coSkillEnd)
        KTool.SetActive(go, false)
        self.coSkillEnd = nil
    end
    self.coSkillEnd = cs_coroutine.start(function()
        KTool.SetActive(go, true)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(SHOW_TIME))
        KTool.SetActive(go, false)
    end) 
end

